"""Catálogo de desafios não violentos do EcoMissão."""
CHALLENGES=[{"id":"agua-01","category":"água","title":"Banho consciente","question":"Você percebe que o banho está demorando mais que o necessário. O que fazer?","options":[{"id":"a","text":"Reduzir o tempo e fechar o chuveiro ao se ensaboar","points":20},{"id":"b","text":"Continuar igual porque uma vez não faz diferença","points":5},{"id":"c","text":"Deixar o chuveiro ligado enquanto procura a toalha","points":0}],"best_option":"a","feedback":"Economizar água em pequenas rotinas reduz desperdício e cria um hábito sustentável."},{"id":"energia-01","category":"energia","title":"Sala vazia","question":"Você saiu de uma sala e ninguém ficará lá. Qual é a melhor ação?","options":[{"id":"a","text":"Apagar as luzes e desligar equipamentos sem uso","points":20},{"id":"b","text":"Deixar tudo ligado para voltar mais tarde","points":0},{"id":"c","text":"Apagar apenas uma das luzes","points":10}],"best_option":"a","feedback":"Reduzir consumo desnecessário de energia é uma medida simples e eficiente."},{"id":"residuos-01","category":"resíduos","title":"Separação de resíduos","question":"Depois de um lanche, há uma garrafa plástica limpa. O que fazer?","options":[{"id":"a","text":"Colocar no coletor adequado para recicláveis","points":20},{"id":"b","text":"Misturar com resíduos orgânicos","points":0},{"id":"c","text":"Guardar sem destino definido","points":5}],"best_option":"a","feedback":"A separação correta facilita o reaproveitamento de materiais recicláveis."},{"id":"mobilidade-01","category":"mobilidade","title":"Trajeto curto","question":"Você precisa percorrer um trajeto curto e seguro no bairro. Qual opção tende a ser mais sustentável?","options":[{"id":"a","text":"Caminhar ou usar bicicleta quando for apropriado","points":20},{"id":"b","text":"Usar um carro sozinho para qualquer distância","points":0},{"id":"c","text":"Adiar o compromisso sem necessidade","points":5}],"best_option":"a","feedback":"Em trajetos adequados, mobilidade ativa reduz emissões e ainda promove bem-estar."},{"id":"consumo-01","category":"consumo","title":"Compra planejada","question":"Antes de comprar um item novo, qual atitude é mais consciente?","options":[{"id":"a","text":"Verificar se o item é realmente necessário e comparar alternativas duráveis","points":20},{"id":"b","text":"Comprar imediatamente só porque está em promoção","points":0},{"id":"c","text":"Comprar dois para decidir depois","points":0}],"best_option":"a","feedback":"Planejar compras ajuda a reduzir desperdício, gastos e descarte prematuro."}]
